namespace System.Windows.Controls;

public abstract partial class Panel
{
	/// <summary>Identifies the <see cref="IsItemsHost"/> dependency property (default false).</summary>
	/// <remarks>Stored only: items are generated by the items-control types, not hosted into this panel.</remarks>
	public static readonly DependencyProperty IsItemsHostProperty = DependencyProperty.Register(
		nameof(IsItemsHost), typeof(bool), typeof(Panel),
		new FrameworkPropertyMetadata(false, FrameworkPropertyMetadataOptions.NotDataBindable));

	/// <summary>Gets or sets whether this panel is the items host of an <see cref="ItemsControl"/>.</summary>
	public bool IsItemsHost
	{
		get => (bool)GetValue(IsItemsHostProperty)!;
		set => SetValue(IsItemsHostProperty, value);
	}
}
